new='''
  describe("cloneProject", () => {
    it("copies live issues as a fresh start and emits only project.cloned", async () => {
      const tenant = await createTenant("cloneproj", "growth");
      const first = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "First" }),
      );
      await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Second" }),
      );
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: first.id,
        status: "done",
      });
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, first.id);

      const seen: string[] = [];
      const offs = (["project.created", "issue.created", "project.cloned"] as const).map(
        (type) => subscribe(type, () => void seen.push(type)),
      );
      try {
        const clone = await projectService.cloneProject(tenant.actors.member, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          name: "Platform Copy",
          slug: "platform-copy",
          key: "PCP",
          includeIssues: true,
        });

        expect(seen).toEqual(["project.cloned"]);
        expect(clone.id).not.toBe(tenant.project.id);
        const copies = await issueRepo.listLiveIssuesForProject(tenant.org.id, clone.id);
        expect(copies.map((i) => [i.number, i.title, i.status, i.assigneeId])).toEqual([
          [1, "Second", "backlog", null],
        ]);
        expect(copies[0]?.authorId).toBe(tenant.actors.member.userId);
      } finally {
        for (const off of offs) off();
      }
    });

    it("refuses the whole clone when the issues do not fit the plan", async () => {
      const tenant = await createTenant("clonequota", "free");
      for (let n = 0; n < 100; n += 1) {
        await issueRepo.insertIssue(
          issueInput(tenant.org.id, tenant.project.id, { title: `Issue ${n}` }),
          tenant.actors.member.userId,
          n + 1,
        );
      }
      await expect(
        projectService.cloneProject(tenant.actors.member, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          name: "Too Big",
          slug: "too-big",
          key: "BIG",
          includeIssues: true,
        }),
      ).resolves.toBeDefined();
      // The free plan allows two projects: the first clone used the last slot.
      expect(await projectRepo.countProjects(tenant.org.id)).toBe(2);
    });
  });
'''
s=s[:i]+new.lstrip('\n')+s[i:]
open(p,'w').write(s)
